function terminalPane(s,g){let head=g?`<div class="pane-head"><span>${icon('terminal')}</span><span class="pane-title">${esc(s.type==='local'?'Local Terminal':s.name+' · '+sessionEndpoint(s))} · #${s.id}</span><span class="dot ${s.state==='failed'?'failed':s.state==='connecting'?'pending':''}"></span><span>${s.state==='online'?'在线':s.state==='connecting'?'连接中':'已断开'}</span>${paneBroadcastButton(s,g)}${ib('pin-pane','pin','置顶成员',`data-session="${s.id}"`)}${ib('pane-menu','more','成员菜单',`data-session="${s.id}"`)}</div>`:'';let body='';if(s.type==='local'&&s.state!=='online'){body=`<div class="connection-message">${icon('alert')}<div><h3>${s.state==='exited'?'Shell 已退出':'本地终端启动失败'}</h3><p>${s.state==='exited'?'退出码 0 · 历史输出已保留。':'无法启动 /bin/zsh：PTY 初始化失败。'}</p><button class="button secondary" data-act="local-restart">重新启动</button> <button class="button ghost" data-act="close-tab" data-value="${s.id}">关闭页签</button></div></div>`;}else if(s.state==='failed'){body=`<div class="connection-message">${icon('alert')}<div><h3>连接未建立</h3><p>连接 ${esc(sessionEndpoint(s))} 超时（15 秒）。请检查地址或网络后重试。</p><button class="button secondary" data-act="retry" data-session="${s.id}">${icon('refresh')}重试连接</button> <button class="button ghost" data-act="close-tab" data-value="${s.id}">关闭页签</button></div></div>`;}else if(s.state==='connecting'){body=`<div class="connection-message">${icon('network')}<div><h3>正在连接 ${esc(s.name)}</h3><p>${s.type==='local'?'正在创建 PTY 并启动登录 Shell…':'建立 SSH 连接，等待认证…'}</p>${s.type==='local'?'':`<button class="button secondary" data-act="auth" data-session="${s.id}">输入认证信息</button>`} <button class="button ghost" data-act="fail-connect" data-session="${s.id}">模拟连接失败</button></div></div>`;}else{body=`<div class="terminal-scroll ${s.timestamp?'terminal-timestamp':''}" data-session="${s.id}">${(historyOn?s.log.slice(0,Math.max(1,Math.ceil(s.log.length*replayPosition/100))):s.log).map((l,i)=>logMarkup(l,s,i)).join('')}${!historyOn?`<form class="input-row" data-session="${s.id}" autocomplete="off"><span class="shell-prompt">${esc(prompt(s))}</span><textarea class="command-input" rows="1" aria-label="${esc(s.name)} 命令输入" spellcheck="false" placeholder="输入命令，或 @ 查看内置指令" data-session="${s.id}">${esc(s.draft)}</textarea></form>`:''}</div><div class="command-palette" id="palette-${s.id}" hidden></div>`;}return `<section class="terminal-pane ${active===s.id?'focused':''}" data-pane="${s.id}" draggable="${!!g}" aria-label="${esc(s.name)} 终端">${head}${body}</section>`;}
function logMarkup(l,s,i){const stamp=l.at||'10:24:16',time=()=>s.timestamp?`<time class="timestamp">${esc(stamp)}</time>`:'',rows=(text,klass='')=>String(text??'').split('\n').map(line=>`<div class="terminal-line ${klass}">${line.trim()?time():''}<span class="terminal-row-content">${esc(line)||' '}</span></div>`).join('');if(l.kind==='app')return `<article class="app-command ${l.state==='failed'?'failed':l.state==='pending'?'pending':''}" data-command="${i}"><div class="command-top">${time()}<span class="command-marker">ZeroWork</span><code>${esc(l.command)}</code><time class="command-executed-at">${esc(new Date().toLocaleDateString('sv-SE')+' '+stamp)}</time></div><div class="command-result">${String(l.output??'').split('\n').map((line,j)=>`<div class="command-result-row"><span class="result-icon">${j?'':l.state==='failed'?'!':l.state==='pending'?'◌':'✓'}</span><span>${esc(line)||' '}</span></div>`).join('')}</div>${l.action?`<div class="result-meta"><button class="command-inline-button" data-act="${l.action}" data-value="${l.target||''}">${l.actionLabel||'查看'}</button></div>`:''}</article>`;if(l.kind==='text')return rows(l.text,l.dim?'dim':'');return `<div class="terminal-line">${time()}<span class="terminal-row-content"><span class="prompt-host">${esc(prompt(s))}</span> ${esc(l.command)}</span></div><div class="terminal-output">${rows(l.output,'pre')}</div>`;}

const catalogue=[['@ai','AI 运维助手','提问内容（可选）'],['@new','新建同类型会话 · 组内自动入组',''],['@dup','镜像复制会话与当前目录',''],['@grp','加入 / 创建终端组','组名'],['@pin','组内置顶当前会话',''],['@sync','开启 / 关闭组输入广播','on|off'],['@ts','切换时间戳',''],['@log','历史回放 · 只读',''],['@theme','全局主题选择','主题名（可选）'],['@help','指令速查',''],['@up','上传文件','本地路径（可选）'],['@dl','下载文件或目录','远端路径'],['@socks','SOCKS5 动态转发','on|off']];
function inputCommand(e){e.target.style.height='auto';e.target.style.height=Math.min(115,Math.max(23,e.target.scrollHeight))+'px';const s=sessions.find(x=>x.id===+e.target.dataset.session);s.draft=e.target.value;active=s.id;renderPalette(s,e.target);}
function positionPalette(p,input){if(p.hidden||!input?.isConnected)return;const pane=p.parentElement,pr=pane.getBoundingClientRect(),app=$('#app').getBoundingClientRect(),ir=input.getBoundingClientRect(),header=pane.querySelector('.pane-head')?.getBoundingClientRect(),top=Math.max(pr.top,app.top+8,header?.bottom||0)+8,bottom=Math.min(pr.bottom,app.bottom-8)-8,left=Math.max(pr.left,app.left+8)+8,right=Math.min(pr.right,app.right-8)-8,gap=6;if(ir.bottom<top||ir.top>bottom){p.hidden=true;return;}p.style.right='auto';p.style.bottom='auto';p.style.width=Math.min(520,Math.max(160,right-left))+'px';p.style.maxHeight='330px';const wanted=Math.min(330,p.scrollHeight),below=Math.max(0,bottom-ir.bottom-gap),above=Math.max(0,ir.top-top-gap),up=below<wanted&&above>below,room=up?above:below;if(room<72){p.hidden=true;return;}p.style.maxHeight=Math.min(330,room)+'px';const x=Math.max(left,Math.min(ir.left,right-p.offsetWidth)),y=up?ir.top-gap-p.offsetHeight:ir.bottom+gap;p.style.left=(x-pr.left)+'px';p.style.top=(y-pr.top)+'px';p.dataset.palettePlacement=up?'above':'below';p.dataset.paletteOwner=input.dataset.session;}
function repositionCommandPalettes(){all('.command-palette:not([hidden])').forEach(p=>{const input=$('.command-input[data-session="'+p.dataset.paletteOwner+'"]');if(input)positionPalette(p,input);else p.hidden=true;});}
function renderPalette(s,input){const p=$(`#palette-${s.id}`);if(!p)return;if(!s.draft.startsWith('@')||s.draft.includes(' ')){renderOtherPalette(s,input,p);return;}let list=catalogue.filter(c=>(s.type!=='local'||!['@up','@dl','@socks'].includes(c[0]))&&c[0].startsWith(s.draft));p.innerHTML=`<div class="palette-head">${icon('terminal')}<strong>本地指令</strong><span class="badge">${s.type==='local'?'ZSH':'SSH'}</span></div><div class="palette-list">${list.map((c,i)=>`<button class="palette-row ${i===0?'active':''}" data-act="adopt" data-value="${c[0]}" data-session="${s.id}">${icon('terminal')}<code>${c[0]}</code><small>${c[1]}</small>${c[2]?'<span class="badge">参数</span>':''}</button>`).join('')||'<p style="padding:10px">无匹配指令</p>'}</div><div class="palette-foot"><span>${list.length} 项</span><span>↑↓ 选择 · ↵ 采纳 / 执行 · Esc 关闭</span></div>`;p.hidden=false;positionPalette(p,input);}
function commandKey(e){const s=sessions.find(x=>x.id===+e.target.dataset.session);if(e.isComposing)return;const p=$(`#palette-${s.id}`);if(e.key==='Escape'){if(p)p.hidden=true;return;}if(p&&!p.hidden&&['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();let rows=[...p.querySelectorAll('.palette-row')],i=rows.findIndex(r=>r.classList.contains('active'));rows.forEach(r=>r.classList.remove('active'));rows[(i+(e.key==='ArrowDown'?1:-1)+rows.length)%rows.length]?.classList.add('active');return;}if(e.key==='Enter'){if(e.shiftKey)return;e.preventDefault();e.stopPropagation();if(p&&!p.hidden){const row=p.querySelector('.palette-row.active');if(row){if(row.dataset.value.trim()===s.draft.trim()){p.hidden=true;execute(s,s.draft);return;}adopt(s,row.dataset.value);return;}}if(s.draft.includes('\n')){const draft=s.draft;modal('发送多行命令？','逐行检查后再发送。',`<pre class="multiline-preview">${esc(draft)}</pre>`,`<button class="button secondary" data-act="close-modal">返回编辑</button><button class="button primary" data-act="confirm-action">确认逐行发送</button>`);pendingFileAction=()=>draft.split(/\r?\n/).filter(l=>l.trim()).forEach(line=>execute(s,line));return;}execute(s,s.draft);}if(e.key==='ArrowRight'&&p&&!p.hidden){const row=p.querySelector('.palette-row.active');if(row){e.preventDefault();adopt(s,row.dataset.value,true);}}}
function adopt(s,name,editOnly=false){const c=catalogue.find(c=>c[0]===name);$(`#palette-${s.id}`).hidden=true;if(!c){s.draft=name;const input=$(`.command-input[data-session="${s.id}"]`);input.value=name;input.focus();input.setSelectionRange(name.length,name.length);return;}s.draft=name+(c[2]?' ':'');const input=$(`.command-input[data-session="${s.id}"]`);input.value=s.draft;input.focus();input.setSelectionRange(input.value.length,input.value.length);if(!c[2]&&!editOnly)execute(s,s.draft);}
function appRecord(s,command,output,state='success',extra={}){const started=Date.now(),record={kind:'app',command,output,state,at:new Date(started).toLocaleTimeString('zh-CN',{hour12:false}),atMs:started,...extra};s.log.push(record);return record;}
function execute(s,raw,origin='command'){const commandOwner=s.id;const record=(session,command,output,state='success',extra={})=>{if(origin==='command')return appRecord(session,command,output,state,extra);if(state!=='pending')toast(output);return {state,output,...extra};};if(!s||!['local','ssh'].includes(s.type)){toast('当前会话不支持终端命令','请切换到Local Terminal 或 SSH 终端。');return;}const text=raw.trim();if(!text)return;if(origin==='command')s.draft='';if(text.startsWith('@@')){s.log.push({kind:'shell',command:text.slice(1),output:'zsh: command not found: '+text.slice(1)});renderContent();return;}if(text.startsWith('@')){const [cmd,...args]=text.split(/\s+/),arg=args.join(' ');if(s.type==='local'&&['@up','@dl','@socks'].includes(cmd)){record(s,text,'此指令只适用于 SSH 会话。','failed');renderContent();return;}switch(cmd){case '@new':case '@dup':createSession(s,cmd==='@dup',origin==='command'?text:null);break;case '@grp':if(!arg){record(s,text,'缺少组名。用法：@grp <组名>；例如 @grp production','failed');s.draft=text+' ';break;}if(arg==='leave'||arg==='off'){const g=currentGroup();if(g)g.members=g.members.filter(id=>id!==s.id);groups=groups.filter(g=>g.members.length);groupMode=false;record(s,text,'已移出组，当前会话继续运行。');break;}let g=groups.find(g=>g.name===arg);if(!g){g={id:Date.now(),name:arg,members:[]};groups.push(g);}if(!g.members.includes(s.id))g.members.push(s.id);active=s.id;groupMode=true;record(s,text,'已加入终端组「'+arg+'」。现有 '+g.members.length+' 个会话。');break;case '@ts':s.timestamp=!s.timestamp;record(s,text,'时间戳已'+(s.timestamp?'开启':'关闭')+'。');break;case '@theme':{if(arg){const normalized=arg.trim().toLowerCase(),selected=normalized==='default'?'dark':themeCatalog.find(([id,name])=>id===normalized||name.toLowerCase()===normalized)?.[0];if(!selected){record(s,text,'未找到主题「'+arg+'」。输入 @theme 选择可用主题。','failed');break;}theme=selected;document.body.dataset.theme=theme;syncThemeURL();record(s,text,'已切换为 '+themeCatalog.find(([id])=>id===theme)[1]+'。');}else{record(s,text,'已打开主题选择。');setTimeout(()=>themePopover(commandRecordAnchor(commandOwner)),0);}break;}case '@help':record(s,text,'可用指令：'+catalogue.filter(c=>s.type!=='local'||!['@up','@dl','@socks'].includes(c[0])).map(c=>c[0]).join('  ')+'\n含参数指令：采纳后继续编辑；应用指令不发送到远端 Shell。');break;case '@log':record(s,text,'已打开独立历史回放页签，实时会话继续运行。');openHistory(s);break;case '@sync':if(!currentGroup()){record(s,text,'请先用 @grp <组名> 加入终端组。','failed');break;}if(arg==='off'){delete approvals[currentGroup().id];broadcast=false;approval=null;record(s,text,'输入广播已停止。');}else if(arg==='on'){record(s,text,'等待确认参与广播的会话。','pending');setTimeout(()=>broadcastPopover(commandRecordAnchor(commandOwner)),0);}else{record(s,text,'开关只接受 on / off。例如 @sync on。','failed');s.draft=text+' ';}break;case '@pin':if(currentGroup()){togglePin(s);record(s,text,s.pinned?'已置顶当前组成员。':'已取消置顶。');}else record(s,text,'当前会话不在终端组中。','failed');break;case '@ai':record(s,text,'已打开 AI 运维助手。'+(arg?'提问已放入当前助手草稿。':''));assistantOpen=true;if(arg)aiData().draft=arg;break;case '@up':record(s,text,'已打开上传确认，尚未传输。');setTimeout(()=>transferDialog('upload'),0);break;case '@dl':if(!arg){record(s,text,'请输入远端路径，例如 @dl /var/log/app.log。','failed');s.draft=text+' ';}else{record(s,text,'已打开下载确认，等待选择保存目录。');setTimeout(()=>transferDialog('download',arg),0);}break;case '@socks':if(!['on','off'].includes(arg)){record(s,text,'用法：@socks on|off。','failed');s.draft=text+' ';}else{const error=arg==='on'?socksError(s):null;if(error){record(s,text,error,'failed');break;}s.socks=arg==='on';const config=s.socksConfig||{bind:'127.0.0.1',port:1080};record(s,text,s.socks?'SOCKS5 已监听 '+config.bind+':'+config.port+'。':'SOCKS5 转发已停止。');}break;default:record(s,text,'未知内置指令。输入 @help 查看可用指令。','failed');s.draft=text;}render();}else{const outputs={'pwd':s.cwd,'ls':'current/    releases/    shared/    deploy.yaml    access.log','ls -lh':'drwxr-xr-x  4 deploy deploy 4.0K  current/\n-rw-r--r--  1 deploy deploy 2.1K  deploy.yaml','git status':'On branch main\nChanges not staged for commit:\n  modified: src/ui/workspace.zig','whoami':s.type==='local'?'developer':'deploy','clear':'','date':'Sun Oct 25 10:24:16 CST 2026'};if(text==='clear'){s.log=[];}else s.log.push({kind:'shell',command:text,at:now(),output:outputs[text]??(text.startsWith('echo ')?text.slice(5):'zsh: command not found: '+text.split(/\s+/)[0])});const shellApproval=Object.values(approvals).find(a=>a.members?.includes(s.id));if(shellApproval){shellApproval.members.filter(id=>id!==s.id&&groups.find(g=>g.id===shellApproval.group)?.members.includes(id)).forEach(id=>{const receiver=sessions.find(x=>x.id===id);if(receiver?.state==='online')receiver.log.push({kind:'shell',command:text,at:now(),output:outputs[text]??(text.startsWith('echo ')?text.slice(5):'zsh: command not found: '+text.split(/\s+/)[0])});});}renderContent();}const input=$(`.command-input[data-session="${s.id}"]`);input?.focus();}
function createSession(source,duplicate,command){let g=groups.find(g=>g.members.includes(source.id));const id=nextId++;const target={id,color:duplicate?source.color:undefined,type:source.type,name:source.type==='local'?'Local Terminal':source.name,user:source.user,address:source.address,port:source.port,shellHost:source.shellHost,route:structuredClone(source.route||[]),cwd:duplicate?source.cwd:source.type==='local'?'/Users/developer':source.user==='root'?'/root':'/home/'+(source.user||'deploy'),state:'connecting',log:[],draft:'',timestamp:false};sessions.push(target);if(g)g.members.push(id);const record=command?appRecord(source,command,`正在${duplicate?'镜像复制':'新建'}会话 #${id}${g?'，将加入「'+g.name+'」':'。'}。`,'pending',{action:'locate-session',target:id,actionLabel:'查看新会话'}):{state:'pending',output:''};if(!g){active=id;groupMode=false;}render();setTimeout(()=>{target.state='online';target.log=[{kind:'text',text:target.type==='local'?'Local Terminal 已就绪。':'SSH 连接已建立。',dim:true},{kind:'shell',command:'pwd',output:target.cwd}];record.state='success';record.output=`已${duplicate?'镜像复制':'新建'}会话 #${id}${g?'，加入原组「'+g.name+'」':'。'}\n${duplicate?'已继承当前目录：'+target.cwd:'新会话使用默认登录目录：'+target.cwd}`;if(!command)toast('会话已'+(duplicate?'复制':'新建'),g?'已加入原终端组':'已在新页签打开');render();},700);}
function switchSession(id){const previous=String(groupMode&&currentGroup()?'g'+currentGroup().id:active);recentTabs=[String(id),...(previous!=='null'&&previous!==String(id)?[previous]:[]),...recentTabs.filter(x=>x!==String(id)&&x!==previous)];if(String(id).startsWith('g')){const g=groups.find(g=>g.id===+String(id).slice(1));if(g){active=g.members[0];groupMode=true;}}else{active=+id;groupMode=false;}hidePopover();render();}
function closeSession(value){if(String(value).startsWith('g')){const g=groups.find(g=>g.id===+String(value).slice(1));if(g)closeGroupDialog(g);return;}let id=+value,closing=sessions.find(s=>s.id===id),ownedJobs=jobs.filter(j=>j.owner===id&&['queued','running','verifying'].includes(j.state));if(ownedJobs.length){confirmDialog('暂停传输并关闭会话？',ownedJobs.length+' 个活动任务将暂停，保留在全局传输管理器中，可稍后继续。','暂停并关闭',()=>{ownedJobs.forEach(j=>j.state='paused');closeSession(id);});return;}if(closing?.type==='local'&&closing.processBusy){confirmDialog('结束活动进程并关闭？','当前 ZSH 正在运行 tail -f。关闭将终止该会话进程。','结束并关闭',()=>{closing.processBusy=false;closeSession(id);});return;}forwards=forwards.filter(f=>f.owner!==id);if(closing)closing.socks=false;sessions=sessions.filter(s=>s.id!==id);groups.forEach(g=>g.members=g.members.filter(x=>x!==id));groups=groups.filter(g=>g.members.length);if(active===id){active=sessions[0]?.id;groupMode=!!currentGroup();}render();}
function renderStatusContent(){let s=current(),g=groupMode?currentGroup():null,a=g?approvals[g.id]:null;if(!s){$('#statusbar').innerHTML=`<span class="status-metric">${icon('terminal')}就绪</span><span class="status-spacer"></span>${ib('theme','palette','全局主题')}`;return;}if(s.type==='history'){$('#statusbar').innerHTML=`<span class="status-metric">${icon('history')}历史回放 · 只读</span><span class="status-metric">${esc(s.sourceName)} · ${s.gap?'含缺口':'记录完整'}</span><span class="status-spacer"></span><button class="status-feature" data-act="export-log">${icon('download')}导出记录</button><button class="status-feature" data-act="history-live">返回实时会话 ${icon('chevron')}</button>`;return;}const local=s.type==='local',file=s.type==='sftp',online=s.state==='online';$('#statusbar').innerHTML=`<button class="status-identity" data-act="identity" data-tip="${local?'本地进程与目录':'会话连接详情'}"><span class="dot ${!online?'failed':''}"></span>${local?'运行中':online?'已连接':'未连接'}${!local&&online?'<span class="connection-latency">12 ms</span>':''}${icon('up')}</button><span class="status-metric">${icon('type')}UTF-8</span>${!file?`<span class="status-metric optional">${icon('expand')}${g?'72 × 32':'138 × 36'}</span>`:''}<span class="status-spacer"></span><button id="broadcast" class="status-feature ${a?'on':''}" data-act="broadcast" data-tip="${g?'终端组输入广播':'创建或加入终端组后开启广播'}">${icon('radio')}<span>广播${a?' · 已开':''}</span></button><button class="status-feature" data-act="chain" data-tip="${local?'本地进程链路':'连接链路与跳板详情'}">${icon('network')}<span>连接链路</span></button><button class="status-feature" data-act="forward" data-tip="本地、远端及 SOCKS5 端口转发">${icon('plug')}<span>端口转发${forwards.filter(f=>f.owner===s.id&&f.running).length+(s.socks?1:0)?' · '+(forwards.filter(f=>f.owner===s.id&&f.running).length+(s.socks?1:0)):''}</span></button><button id="status-theme" class="icon-btn" data-act="theme" data-tip="全局主题" aria-label="全局主题">${icon('palette')}</button><button class="transfer-summary" data-act="transfer-popover" data-tip="当前传输与全局任务">${icon('transfer')}<span class="summary-text">文件传输${jobs.some(j=>j.state==='running')?' · '+jobs.filter(j=>['queued','running','verifying'].includes(j.state)).length+' 项':jobs.length?' · '+jobs.length+' 项':' · 空闲'}</span>${icon('up')}</button>`;}

function popover(anchor,title,ico,body,footer=''){window.V3Materials?.setOwner($('#popover'),anchor);$('#popover').removeAttribute('data-compression-usage');$('#tooltip').hidden=true;closeContext();const p=$('#popover');p.classList.remove('ap-resource-popover');p.style.width='344px';p.innerHTML=`<div class="popover-head">${icon(ico)}<strong>${title}</strong>${ib('close-popover','x','关闭浮卡')}</div>${body}${footer?`<div class="popover-foot">${footer}</div>`:''}`;p.hidden=false;if(!anchor?.closest?.('#popover')){popoverAnchor=anchor;popoverAnchorRect=actionAnchorRects.get(anchor)||anchor?.getBoundingClientRect?.();popoverAnchorKey=anchor?.matches?.('.app-command')?'[data-pane="'+anchor.closest('[data-pane]').dataset.pane+'"] .app-command[data-command="'+anchor.dataset.command+'"]':anchor?.id?'#'+CSS.escape(anchor.id):anchor?.closest?.('#statusbar')?'#statusbar [data-act="'+anchor.dataset.act+'"]':anchor?.dataset?.act?'[data-act="'+anchor.dataset.act+'"]'+(anchor.dataset.session?'[data-session="'+anchor.dataset.session+'"]':''):null;}positionPopover();}
function placeOverlay(p,r,preferUp=false){const a=$('#app').getBoundingClientRect(),pad=12,gap=8,above=Math.max(0,r.top-a.top-pad-gap),below=Math.max(0,a.bottom-r.bottom-pad-gap);p.style.maxHeight=(a.height-pad*2)+'px';const wanted=p.offsetHeight,up=preferUp?above>=96:below<wanted&&above>below,space=up?above:below;p.style.maxHeight=Math.max(48,space)+'px';const left=Math.max(pad,Math.min(r.left-a.left,a.width-p.offsetWidth-pad)),top=up?r.top-a.top-p.offsetHeight-gap:r.bottom-a.top+gap;p.style.left=left+'px';p.style.top=Math.max(pad,Math.min(top,a.height-p.offsetHeight-pad))+'px';}
function positionAssistantPopover(p,anchor,rect){
 const app=$('#app').getBoundingClientRect(),gap=6,left=Math.max(8,app.left+8),right=Math.min(innerWidth-8,app.right-8),top=Math.max(8,app.top+8),bottom=Math.min(innerHeight-8,app.bottom-8);p.dataset.aiAnchored='true';p.style.maxHeight='none';p.style.overflowY='visible';p.style.width=Math.min(parseFloat(p.style.width)||p.offsetWidth||344,Math.max(120,right-left))+'px';p.style.maxWidth=Math.max(120,right-left)+'px';
 const above=Math.max(0,rect.top-top-gap),below=Math.max(0,bottom-rect.bottom-gap),preferBelow=!!anchor?.closest('.v3-ai-head'),up=preferBelow?below<120&&above>below:above>=100||above>=below,room=Math.max(40,up?above:below);p.style.maxHeight=room+'px';p.style.overflowY='auto';const height=p.offsetHeight,x=Math.max(left,Math.min(rect.left,right-p.offsetWidth)),y=up?rect.top-gap-height:rect.bottom+gap;p.style.left=(x-app.left)+'px';p.style.top=(Math.max(top,Math.min(y,bottom-height))-app.top)+'px';p.dataset.aiPlacement=up?'above':'below';
}
function positionPopover(){const p=$('#popover');if(p.hidden)return;if(popoverAnchorKey){const live=$(popoverAnchorKey);if(live)popoverAnchor=live;}const liveRect=popoverAnchor?.isConnected?popoverAnchor.getBoundingClientRect():null;const rect=liveRect?.width&&liveRect?.height?liveRect:popoverAnchorRect;if(!rect)return;if(popoverAnchor?.closest?.('#assistant')){positionAssistantPopover(p,popoverAnchor,rect);window.V3Feedback?.reportOverlay('popover',p);positionToasts();return;}if(p.dataset.aiAnchored){p.style.maxHeight='';p.style.maxWidth='';p.style.overflowY='';}delete p.dataset.aiAnchored;delete p.dataset.aiPlacement;placeOverlay(p,rect,!!popoverAnchor?.closest?.('.statusbar'));if(p.querySelector('[data-transfer-panel]')){const app=$('#app').getBoundingClientRect(),visibleTop=Math.max(12,app.top+12),visibleBottom=Math.min(innerHeight-12,app.bottom-12),available=Math.max(48,visibleBottom-visibleTop);p.style.maxHeight=Math.min(parseFloat(p.style.maxHeight)||available,available)+'px';const bounds=p.getBoundingClientRect();if(bounds.right>innerWidth-12)p.style.left=(parseFloat(p.style.left)||0)-(bounds.right-innerWidth+12)+'px';else if(bounds.left<12)p.style.left=(parseFloat(p.style.left)||0)+(12-bounds.left)+'px';p.style.top=Math.max(visibleTop-app.top,Math.min(bounds.top-app.top,visibleBottom-app.top-bounds.height))+'px';}V3Feedback.reportOverlay('popover',p);positionToasts();}
