function identityPopover(a){let s=current();popover(a,s.type==='local'?'本地终端身份':'会话连接','terminal',details(s.type==='local'?[['Shell','/bin/zsh · 登录 Shell'],['进程','PID 43812 · 运行中'],['当前目录',esc(s.cwd)],['终端','xterm-256color'],['会话','#'+s.id]]:[['连接',esc(s.name)],['身份',esc(sessionEndpoint(s))],['协议',s.type==='sftp'?'SFTP · SSH 文件子系统':'SSH · 交互式 Shell'],['状态',s.state==='online'?'在线':'连接失败'],['延迟',s.state==='online'?'12 ms':'—'],['加密','chacha20-poly1305'],['会话','#'+s.id]]),`<button class="button secondary" data-act="copy-info">${icon('copy')}复制信息</button><span class="spacer"></span>${s.type==='local'?'<button class="button ghost" data-act="local">新建本地会话</button>':`<button class="button ghost" data-act="retry" data-session="${s.id}">重新连接</button>`}`);}
