let connectionDraftHostIndex=-1;let contextReturnFocus=null,contextSelection='';function menu(anchor,items){const anchorRect=anchor instanceof Element?(actionAnchorRects.get(anchor)||anchor.getBoundingClientRect()):anchor;contextReturnFocus=document.activeElement;contextSelection=document.getSelection()?.toString()||'';$('#tooltip').hidden=true;hidePopover();let p=$('#context-menu');p.classList.remove('file-context-v3');p.innerHTML=items.map(i=>i===null?'<div class="menu-divider"></div>':`<button role="menuitem" class="menu-item ${i.danger?'danger':''}" ${i.disabled?'disabled':''} ${i.reason||i.disabled?`title="${esc(i.reason||'当前状态不可用')}" data-tip="${esc(i.reason||'当前状态不可用')}"`:''} data-act="${i.act}" ${i.value!==undefined?`data-value="${i.value}"`:''} ${i.session?`data-session="${i.session}"`:''} ${i.side?`data-side="${i.side}"`:''}>${icon(i.icon||'terminal')}<span>${i.label}</span>${i.key?`<kbd>${i.key}</kbd>`:''}</button>`).join('');p.setAttribute('role','menu');p.hidden=false;let r=anchorRect;if(anchor?.closest?.('#assistant'))positionAssistantPopover(p,anchor,r);else{delete p.dataset.aiAnchored;delete p.dataset.aiPlacement;p.style.maxHeight='';p.style.maxWidth='';p.style.overflowY='';placeOverlay(p,{left:r.left,top:r.top,bottom:r.bottom??r.top},!!anchor?.closest?.('.statusbar'));}p.querySelector('button:not(:disabled)')?.focus();V3Feedback.reportOverlay('menu',p);}
