function modalHeading(title){
 const name=/^上下文附件$/.test(title)?'paperclip':/^图片预览$/.test(title)?'image':/附加远端文件|选择远端连接/.test(title)?'fileSearch':/文件预览|文件读取预览/.test(title)?'file':/关闭.*终端组|终端组关闭结果/.test(title)?'circleAlert':/不可用$/.test(title)?'circleAlert':/^删除/.test(title)?'trash':/历史|归档/.test(title)?'history':/多行命令/.test(title)?'clipboardPaste':/导出|另存为/.test(title)?'download':/模型能力|SOCKS5 配置|添加端口转发/.test(title)?'sliders':/SSH 认证/.test(title)?'lock':/测试连接链路/.test(title)?'network':/同名文件/.test(title)?'files':/移动主机分组/.test(title)?'folderInput':/重命名页签/.test(title)?'edit':/终端组|新工作区窗口/.test(title)?'group':/文件属性/.test(title)?'info':null;
 return name?`<span class="semantic-heading ${name==='circleAlert'||name==='clipboardPaste'?'warning':name==='trash'?'danger':''}">${icon(name)}<span>${esc(title)}</span></span>`:title;
}
