function closeModal(){$('#modal-root').hidden=true;$('#modal-root').innerHTML='';lastFocus?.focus?.();V3Feedback.reportOverlay('modal',null);}
function confirmDialog(title,message,action,callback){pendingFileAction=callback;modal(title,'请确认当前操作',`<p style="font-size:12px">${esc(message)}</p>`,`<button class="button secondary" data-act="close-modal">取消</button><button class="button danger-solid" data-act="confirm-action">${action}</button>`);}
