function tabSessionMenu(anchor){menu(anchor,[{act:'local',icon:'terminal',label:'本地终端'},...recentMenuHosts().map(h=>({act:'host-new',value:hosts.indexOf(h),icon:h.tag==='SFTP'?'folder':'server',label:esc(h.name)})),{act:'session-more',icon:'chevron',label:'更多'},null,{act:'connection',icon:'server',label:'新建主机'},{act:'new-sftp',icon:'folder',label:'新建 SFTP'}]);const root=$('#context-menu');root.dataset.sessionMenu='true';root.querySelector('[data-act="connection"]').insertAdjacentHTML('beforebegin','<div class="menu-caption">快捷连接</div>');const more=root.querySelector('[data-act="session-more"]');if(!recentMenuHosts().length)more.insertAdjacentHTML('beforebegin','<div class="menu-caption">暂无最近连接</div>');more.setAttribute('aria-haspopup','menu');more.append(more.querySelector('svg'));more.addEventListener('pointerenter',()=>showMoreHosts(more));more.addEventListener('focus',()=>{if(more.dataset.skipMore){delete more.dataset.skipMore;return;}showMoreHosts(more);});more.addEventListener('pointerleave',()=>scheduleMoreClose(more));more.addEventListener('keydown',e=>{if(e.key==='ArrowRight'){e.preventDefault();showMoreHosts(more);$('#session-more-menu button')?.focus();}});}
let moreCloseTimer=null;function scheduleMoreClose(anchor){clearTimeout(moreCloseTimer);moreCloseTimer=setTimeout(()=>{const panel=$('#session-more-menu');if(panel&&!panel.matches(':hover')&&!anchor.matches(':hover')&&!panel.contains(document.activeElement)&&document.activeElement!==anchor)panel.hidden=true;},180);}
