let quickSelected=0;
function quickConnectDialog(){modal(`${icon('bolt')}快速连接`,'',`<label class="quick-search">${icon('search')}<input id="quick-query" placeholder="搜索主机或输入 SSH 目标" autocomplete="off" aria-label="搜索主机或输入 SSH 目标"><kbd>⌘K</kbd></label><div id="quick-results"></div><div id="quick-target" hidden></div><p class="quick-keyboard">↑↓ 选择 · Enter 连接 · Esc 关闭</p>`,`<button class="button secondary" data-act="connection">新建主机配置</button><span class="spacer"></span><button class="button primary" id="quick-submit" data-act="quick-submit">连接所选主机</button>`);$('#modal-root .modal').classList.add('quick-connect-palette');quickSelected=0;renderQuickResults();$('#quick-query').addEventListener('input',()=>{quickSelected=0;renderQuickResults();});$('#quick-query').addEventListener('keydown',e=>{const rows=[...$('#quick-results').querySelectorAll('[data-act="host-new"]')];if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();quickSelected=(quickSelected+(e.key==='ArrowDown'?1:-1)+rows.length)%Math.max(rows.length,1);rows.forEach((n,i)=>n.classList.toggle('selected',i===quickSelected));rows[quickSelected]?.scrollIntoView({block:'nearest'});}if(e.key==='Enter'&&!e.isComposing){e.preventDefault();e.stopPropagation();$('#quick-submit').click();}});}
function quickTarget(){const raw=$('#quick-query')?.value.trim().replace(/^ssh\s+/,'')||'',m=raw.match(/^([^\s@]+)@(\[[^\]]+\]|[^\s:]+)(?::(\d+))?$/);if(!m)return null;const port=+(m[3]||22);return port>0&&port<=65535?{user:m[1],address:m[2].replace(/^\[|\]$/g,''),port}:null;}
