function putAiAttachment(name,snapshot,d=aiData()){d.attachmentSnapshots=d.attachmentSnapshots||{};const identity=JSON.stringify([name,snapshot.type,snapshot.source,snapshot.size,snapshot.lastModified,snapshot.text]),prior=Object.entries(d.attachmentSnapshots).find(([,item])=>item.identity===identity);if(prior)return prior[0];let key=name,n=1;while(d.attachmentSnapshots[key])key=name+' · '+(snapshot.source||'附件')+' '+(++n);d.attachments.push(key);d.attachmentSnapshots[key]={...snapshot,name,identity};return key;}
