function aiConversationActive(d){return !!(d?.running||d?.stopping||d?.compression?.state==='running'||['running','approval','stopping'].includes(d?.prototypePrimaryState)||d?.messages?.some(m=>/await_confirm|ai-tool-approve|data-ui-active="true"/.test(m)));}
function confirmAiConversationDelete(key){const entry=allAiConversations().find(c=>c.key===key);if(!entry)return;aiPendingDelete=key;if(!aiConversationActive(entry.state)){deleteAiConversation();return;}const copy=V3AI.closePrompt;modal(copy.title,copy.detail,'',`<button class="button secondary" data-act="close-modal">取消</button><button class="button danger-solid" data-act="ai-session-delete-confirm">${copy.confirm}</button>`);$('#modal-root .modal').classList.add('ai-session-confirm');$('#modal-root .modal-title h2').insertAdjacentHTML('afterbegin','<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 8v4m0 4h.01"/></svg>');}
function deleteAiConversation(){const currentOwner=assistantOwner(),currentId=aiData().id;const entry=allAiConversations().find(c=>c.key===aiPendingDelete);if(!entry)return;entry.state.running=false;if(entry.state.compression?.state==='running')entry.state.compression={...entry.state.compression,state:'cancelled',generation:entry.state.compression.generation+1};aiConversations[entry.owner]=(aiConversations[entry.owner]||[]).filter(c=>c.id!==entry.id);if(aiState[entry.owner]?.id===entry.id){const next=aiConversations[entry.owner]?.shift();aiState[entry.owner]=next?structuredClone(next.state):{id:aiConversationId++,suppressedFromList:true,draft:'',messages:[],permission:entry.state.permission,model:entry.state.model,effort:entry.state.effort,attachments:[],running:false};}aiConversationViews.delete(entry.id);aiPendingDelete=null;closeModal();aiSessionListOpen=true;if(currentOwner===entry.owner&&currentId===entry.id&&aiState[entry.owner]?.suppressedFromList){const next=allAiConversations()[0];if(next){jumpAiConversation(next.key);return;}}renderAssistant();}


function forwardPopover(anchor){if(current()?.type!=='ssh'){popover(anchor,'端口转发','plug','<p>请切换到在线 SSH 终端配置转发。</p>');return;}const owner=current(),rows=forwards.filter(f=>f.owner===owner.id),config=owner.socksConfig||{bind:'127.0.0.1',port:1080};popover(anchor,'端口转发','plug',`<p>每个 SSH 会话同时运行一个转发。停止后可切换模式。</p><div id="forward-list">${rows.length?forwardList():''}${owner.socks?`<div class="member"><span class="badge">SOCKS5</span><div><strong>${esc(config.bind)}:${config.port}</strong><small>本机监听 · 动态目标 · 监听中</small></div><button class="icon-btn" data-act="socks-toggle" aria-label="停止 SOCKS5">${icon('pause')}</button></div>`:''}${!rows.length&&!owner.socks?'<div class="forward-empty">'+icon('plug')+'<strong>没有转发规则</strong><p>本地 L · 远端 R · 动态 SOCKS5</p></div>':''}</div>`,'<button class="button primary" data-act="forward-add">＋ 添加转发</button>');}
function forwardList(){const rows=forwards.filter(f=>f.owner===current()?.id);return rows.map(f=>`<div class="member"><span class="badge">${f.type==='local'?'L':'R'}</span><div><strong>${esc(f.bind)} → ${esc(f.target)}</strong><small>${f.type==='local'?'本机监听 → SSH 端目标':'SSH 端监听 → 本机目标'} · ${f.running?'监听中':'已停止'}</small></div><button class="icon-btn" data-act="forward-toggle" data-value="${f.id}" aria-label="${f.running?'停止':'启动'}转发">${icon(f.running?'pause':'play')}</button><button class="icon-btn" data-act="forward-delete" data-value="${f.id}" aria-label="删除转发">${icon('trash')}</button></div>`).join('');}
function forwardCreateDialog(mode='local'){modal('添加端口转发','规则属于当前 SSH 会话；同一时间只运行一个转发。',`<div class="forward-mode-cards">${[['local','本地 L','本机监听'],['remote','远端 R','SSH 端监听'],['socks','SOCKS5','动态目标']].map(([id,title,detail])=>`<button class="${mode===id?'selected':''}" data-act="forward-create-mode" data-value="${id}"><strong>${title}</strong><small>${detail}</small></button>`).join('')}</div><input type="hidden" id="forward-type" value="${mode}"><p class="info-note">${mode==='local'?'本机监听 → 经 SSH 连接访问目标主机和端口。':mode==='remote'?'SSH 服务器监听 → 回到本机可达的目标 IP 和端口。': '本机监听 → 由 SOCKS5 客户端在每次请求中指定目标。'}</p><label class="field"><span>${mode==='remote'?'SSH 端':'本机'}监听地址与端口</span><input id="forward-bind" value="127.0.0.1:${mode==='socks'?1080:8080}" placeholder="127.0.0.1:8080"></label>${mode!=='socks'?`<label class="field"><span>${mode==='remote'?'本机可达的目标 IP 与端口':'SSH 端可达的目标主机与端口'}</span><input id="forward-target" value="127.0.0.1:80"></label>`:''}<p id="forward-error" class="error-text" hidden></p><p>默认仅回环监听。外部地址监听需要确认；远端监听是否允许由 SSH 服务端决定。</p>`,`<button class="button secondary" data-act="close-modal">取消</button><button class="button primary" data-act="forward-save">添加并启动</button>`);}

function transferEmpty(kind='global'){return `<div class="transfer-empty"><span class="transfer-empty-icon">${icon('transfer')}</span><div><strong>${kind==='session'?'当前没有传输任务':'没有传输任务'}</strong><p>${kind==='session'?'选择文件后上传或下载。':'从文件工作区或 @up / @dl 开始。'}</p></div></div>`;}
function transferPanel(kind,list,direction=''){const owners=[...new Map(list.map(j=>[j.owner,j.ownerName||'来源会话'])).entries()].sort((a,b)=>{const order=id=>{const i=tabOrder.indexOf(String(id));return i<0?999:i};return order(a[0])-order(b[0])});return `<div data-transfer-direction="${direction}" data-transfer-panel="${kind}" data-transfer-empty="${list.length===0}">${!direction?`<div class="transfer-scope-bar">${kind==='global'?V3.tab({label:'全部会话',active:true,closable:false,attrs:{'data-transfer-scope':'all'}}):'<span>当前会话</span>'}${kind==='global'?owners.map(([id,name])=>V3.tab({label:name,closable:false,attrs:{'data-transfer-scope':id}})).join(''):''}</div><input class="transfer-search-input" data-transfer-search placeholder="搜索文件名或路径…" aria-label="搜索传输任务" hidden><div class="transfer-phase-counts">${[['running','进行中'],['queued','等待'],['paused','暂停'],['failed','失败'],['done','结束']].map(([phase,label])=>`<button data-act="transfer-filter" data-value="${phase}">${label} ${list.filter(j=>phase==='running'?['running','verifying'].includes(j.state):phase==='done'?['done','cancelled'].includes(j.state):j.state===phase).length}</button>`).join('')}<span class="spacer"></span><button class="transfer-manage" data-transfer-manage>管理</button><button class="transfer-toolbar-icon" data-transfer-search-toggle aria-label="搜索传输任务">${icon('search')}</button><button class="transfer-toolbar-icon" data-transfer-filter-toggle aria-label="筛选传输状态">${icon('filter')}</button></div>`:''}<div class="transfer-list" data-transfer-jobs ${kind==='global'?'data-job-list':''}>${list.length?jobList(list,kind):transferEmpty(kind)}</div>${!direction?`<footer class="transfer-panel-footer"><span>${kind==='global'?'全部会话':'当前会话'}</span><span data-transfer-summary>${list.filter(j=>j.state==='running').length} 进行中 · ${list.filter(j=>j.state==='queued').length} 等待</span><button data-act="open-sftp" aria-label="打开 SFTP 新建传输" title="打开 SFTP 新建传输">${icon('plus')}</button><button data-transfer-filter-toggle aria-label="显示或隐藏状态筛选" title="状态筛选">${icon('more')}</button></footer>`:''}</div>`;}

function sizeTransferPopover(){const p=$('#popover'),panel=p.querySelector('[data-transfer-panel]');if(!panel)return;const head=p.querySelector('.popover-head');if(head&&!head.querySelector('[data-transfer-owner-badge]'))head.querySelector('strong').insertAdjacentHTML('afterend',`<span class="transfer-owner-badge" data-transfer-owner-badge>${icon('lock')}${panel.dataset.transferPanel==='global'?'全局':'当前会话'}</span>`);p.style.width=Math.min(panel.dataset.transferEmpty==='true'?320:760,innerWidth-24)+'px';p.style.maxHeight=Math.min(panel.dataset.transferPanel==='global'?578:420,innerHeight-24)+'px';positionPopover();}
function transferPopover(anchor){popover(anchor,'传输任务','transfer',transferPanel('session',jobs.filter(j=>j.owner===active)),'');sizeTransferPopover();}

function renderFiles(){$('#content').innerHTML=`<div class="sftp-workspace"><div class="sftp-dual">${fileColumn('local')}${fileColumn('remote')}</div></div>`;syncFileChecks();all('.file-search input').forEach(n=>n.addEventListener('input',e=>{fileQuery[e.target.dataset.side]=e.target.value;updateFileRows(e.target.dataset.side);}));}
function fileTransferTray(side){const direction=side==='local'?'upload':'download',list=jobs.filter(j=>j.owner===active&&j.direction===direction);return list.length?`<section class="session-transfer-tray" data-transfer-side="${side}"><header><strong>${direction==='upload'?'上传':'下载'}传输</strong></header>${transferPanel('session',list,direction)}</section>`:'';}
function filePane(side){return `<section class="file-panel ${activeSide===side?'active':''}" data-side="${side}"><header class="file-header"><div class="file-title">${icon(side==='local'?'home':'server')}<strong>${side==='local'?'本地文件':'远端文件'}</strong><span class="badge">${side==='local'?'MacBook Pro':esc(current()?.name||'远端')}</span><small></small>${ib('file-refresh','refresh','刷新'+(side==='local'?'本地':'远端')+'目录',`data-side="${side}"`)}</div><div class="file-nav">${ib('file-back','back','返回上个目录',`data-side="${side}"`)}${ib('file-up','up','上级目录',`data-side="${side}"`)}<div class="breadcrumb" data-act="edit-path" data-side="${side}" data-tip="点击编辑路径">${directory[side].split('/').filter(Boolean).map((x,i,arr)=>`<button data-act="file-path-part" data-side="${side}" data-value="/${arr.slice(0,i+1).join('/')}">${esc(x)}</button>${i<arr.length-1?'<span>/</span>':''}`).join('')}</div></div><div class="file-filter-row"><label class="file-search">${icon('search')}<input placeholder="筛选当前目录…" aria-label="筛选${side==='local'?'本地':'远端'}文件" data-side="${side}" value="${esc(fileQuery[side])}"></label>${ib('file-mkdir','plus','新建文件夹',`data-side="${side}"`)}${ib('file-menu','more','文件工具',`data-side="${side}"`)}</div></header>${fileState[side]==='stale'?'<div class="stale-note">连接中断 · 显示上次缓存，操作不可提交</div>':''}<div class="file-table-wrap"><table class="file-table"><thead><tr><th><input type="checkbox" data-act="file-select-all" data-side="${side}" aria-label="选择全部${side==='local'?'本地':'远端'}文件"></th><th><button data-act="file-sort" data-side="${side}">名称</button></th><th><button data-act="file-sort" data-side="${side}" data-value="size">大小</button></th><th><button data-act="file-sort" data-side="${side}" data-value="modified">修改时间</button></th></tr></thead><tbody id="file-rows-${side}">${fileRows(side)}</tbody></table></div><div class="file-meta"><span>${files[side].length} 个项目</span><span>${side==='local'?'可用 148.6 GB':'可用 62.4 GB'}</span><button class="icon-btn file-transfer-button" data-act="${side==='local'?'upload':'download'}" aria-label="${side==='local'?'上传到右侧':'下载到左侧'}" data-tip="${side==='local'?'上传本地所选文件到远端':'下载远端所选文件到本地'}">${icon(side==='local'?'upload':'download')}</button></div></section>`;}
function fileColumn(side){return `<div class="file-column" data-transfer-column="${side}">${filePane(side)}${fileTransferTray(side)}</div>`;}
function fileRows(side){if(fileState[side]==='loading')return '<tr><td colspan="4" class="file-state">◌ 正在获取目录…</td></tr>';if(fileState[side]==='error')return `<tr><td colspan="4" class="file-state">${icon('alert')}目录读取失败 · SFTP_CHANNEL_CLOSED<br><button class="text-button" data-act="file-state" data-value="ready" data-side="${side}">重试</button></td></tr>`;if(fileState[side]==='empty')return '<tr><td colspan="4" class="file-state">'+icon('folder')+'此目录为空</td></tr>';return files[side].filter(f=>f.name.toLowerCase().includes(fileQuery[side].toLowerCase())).map((f,i)=>`<tr data-file="${esc(f.name)}" data-side="${side}" draggable="true" class="${selections[side].has(f.name)?'selected':''}" tabindex="0"><td><input type="checkbox" aria-label="选择 ${esc(f.name)}" data-act="file-check" data-side="${side}" data-value="${esc(f.name)}" ${selections[side].has(f.name)?'checked':''}></td><td><div class="file-name"><span class="${f.type==='folder'?'folder-icon':''}">${fileTypeGlyph(f)}</span><span class="filename" data-tip="${esc(directory[side]+'/'+f.name)}">${esc(f.name)}</span></div></td><td>${f.size}</td><td>${f.modified}</td></tr>`).join('')||'<tr><td colspan="4" style="text-align:center;height:160px;color:var(--muted)">此目录没有匹配的文件</td></tr>';}
function updateFileRows(side){$('#file-rows-'+side).innerHTML=fileRows(side);syncFileChecks();}
function setSide(side){activeSide=side;selected=selections[side];}
function navigate(side,path){fileCache[side][directory[side]]=files[side];pathHistory[side].push(directory[side]);directory[side]=path||'/';setSide(side);selected.clear();fileQuery[side]='';seedFiles(side);renderFiles();}
function fileNameDialog(kind,side){setSide(side||activeSide);let f=files[activeSide].find(f=>selected.has(f.name));if(kind==='rename'&&!f){toast('请先选择一个文件或目录。');return;}modal(kind==='rename'?'重命名':'新建文件夹',directory[activeSide]+(f?'/'+f.name:''),`<label class="field"><span>${kind==='rename'?'新名称':'文件夹名称'}</span><input id="file-name-draft" value="${kind==='rename'?esc(f.name):'new-folder'}" aria-label="${kind==='rename'?'新名称':'文件夹名称'}"><small>名称不能包含 /，也不能与当前目录的项目重名。</small></label><p id="file-name-error" class="error-text" hidden></p>`,`<button class="button secondary" data-act="close-modal">取消</button><button class="button primary" data-act="file-name-save" data-value="${kind}">${kind==='rename'?'保存名称':'创建文件夹'}</button>`);}
function transferDialog(direction,path){if(['local','remote'].some(k=>fileState[k]!=='ready')){toast('目录尚未就绪','请先刷新失败、加载中或断线缓存的目录，再进行传输。');return;}if(current()?.type==='sftp'&&!selections[direction==='upload'?'local':'remote'].size){toast('请先选择要'+(direction==='upload'?'上传':'下载')+'的文件','选择项目后再确认目标路径。');return;}let sourceSelection=selections[direction==='upload'?'local':'remote'];let names=sourceSelection.size?[...sourceSelection]:[direction==='upload'?'release-0.2.1.tar.gz':'deploy.yaml'];if(path)names=[path.split('/').pop()];pendingFileAction={direction,names,sourceNames:[...names],path};if(current()?.type==='sftp'){const upload=direction==='upload',source=directory[upload?'local':'remote'],target=directory[upload?'remote':'local'];modal(upload?'上传文件':'下载文件',upload?'本地文件 → 远端目录':'远端文件 → 本地保存目录',`<div class="upload-choice"><span class="copy-summary-icon">${icon('file')}</span><div><strong title="${esc(names.join('、'))}">${esc(names[0])}${names.length>1?' 等 '+names.length+' 个项目':''}</strong><small>已选择 ${names.length} 项 · ${esc(current().name)}</small></div></div><label class="copy-path-field"><span>${upload?'本地来源目录':'远端来源目录'}</span><code class="copy-path-well" title="${esc(source)}">${esc(source)}</code></label><label class="copy-path-field"><span>${upload?'远端目标目录':'本地保存目录'}</span><input id="transfer-path" value="${esc(target)}" readonly title="${esc(target)}"></label><div class="copy-options"><label><input type="checkbox" id="transfer-resume" checked>断点续传</label><label><input type="checkbox" id="verify-md5">完成后校验 MD5</label></div><p class="copy-policy">遇到同名文件时，先询问再处理。</p>`,`<button class="button secondary" data-act="close-modal">取消</button><button class="button primary" data-act="transfer-start">${icon(direction)}${upload?'开始上传':'开始下载'}</button>`);$('#modal-root .modal').classList.add('transfer-copy-v3');$('#modal-root .modal-title h2').insertAdjacentHTML('afterbegin',icon(upload?'upload':'download'));return;}modal(direction==='upload'?'上传文件':'下载文件',direction==='upload'?'本地文件 → 远端目录':'远端文件 → 本地保存目录',`<div class="upload-choice">${icon(direction==='upload'?'upload':'download')}<div><strong>${esc(names.join('、'))}</strong><small>${names.length} 个项目 · ${direction==='upload'?'本地已选项目':'远端已选项目'}</small></div><span class="badge">${esc(transferSize({direction,names}))}</span></div><label class="field"><span>${direction==='upload'?'远端目标目录':'本地保存目录'}</span><div style="display:flex;gap:7px"><input id="transfer-path" value="${esc(direction==='upload'?(current()?.cwd||directory.remote):directory.local)}"><button class="button secondary" data-act="pick-directory">${icon('folder')}选择</button></div></label>${direction==='download'?`<label class="field"><span>另存名称</span><input id="transfer-name" value="${esc(names[0])}" placeholder="保留原名"></label>`:''}<div class="transfer-confirm-options"><label class="check-row"><input type="checkbox" id="transfer-resume" checked><span>断点续传</span></label><label class="check-row" style="margin-top:8px"><input type="checkbox" id="verify-md5"><span>完成后校验 MD5</span></label><label class="check-row" style="margin-top:8px"><input type="checkbox" checked><span>完成时通知</span></label></div><label class="check-row"><input type="checkbox" id="simulate-checksum-fail"><span>演示 MD5 校验失败</span></label><label class="check-row"><input type="checkbox" id="simulate-conflict"><span>演示同名文件冲突</span></label>`,`<button class="button secondary" data-act="close-modal">取消</button><button class="button primary" data-act="transfer-start">${direction==='upload'?'开始上传':'开始下载'}</button>`);}
function startTransfer(){let action=pendingFileAction;if(action&&typeof action!=='function'){action.verify=!!$('#verify-md5')?.checked;action.resume=$('#transfer-resume')?.checked!==false;action.failChecksum=!!$('#simulate-checksum-fail')?.checked;}if(!action||typeof action==='function')return;let dir=$('#transfer-path')?.value||directory.remote;if(!dir.startsWith('/')||dir.includes('\0')){toast('请输入有效的绝对目录路径');return;}let name=$('#transfer-name')?.value||action.names[0];if($('#simulate-conflict')?.checked){pendingFileAction={...action,names:action.names.length>1?action.names:[name],directory:dir};modal('目标已存在同名文件','请选择本次传输的处理方式',`<div class="upload-choice">${icon('file')}<div><strong>${esc(name)}</strong><small>${esc(dir)}</small></div></div><div class="field-grid equal"><div class="card"><h3>目标文件</h3><p>${esc((files[action.direction==='upload'?'remote':'local'].find(f=>f.name===name)||{}).size||'大小待确认')}<br>修改时间待确认</p></div><div class="card"><h3>待传输文件</h3><p>${esc((files[action.direction==='upload'?'local':'remote'].find(f=>f.name===name)||{}).size||'大小待确认')}<br>${esc((files[action.direction==='upload'?'local':'remote'].find(f=>f.name===name)||{}).modified||'修改时间待确认')}</p></div></div><p>覆盖会替换目标内容。</p>`,`<button class="button ghost" data-act="close-modal">取消</button><button class="button secondary" data-act="conflict-skip">跳过</button><button class="button secondary" data-act="conflict-rename">另存为</button><button class="button secondary" data-act="conflict-keep">保留两份</button><button class="button primary" data-act="conflict-replace">覆盖</button>`);return;}queueJob({...action,names:action.names.length>1?action.names:[name],directory:dir});closeModal();}
function completeTransferFiles(job){if(job.state!=='done'||job.filesApplied)return;job.filesApplied=true;const side=job.direction==='upload'?'remote':'local';if(directory[side]===job.path)fileCache[side][job.path]=files[side];const target=fileCache[side][job.path]||(fileCache[side][job.path]=[]);for(const entry of job.entries){const copy={...entry,modified:'刚刚'},old=target.findIndex(f=>f.name===copy.name);if(old<0)target.push(copy);else target[old]=copy;}if(directory[side]===job.path){files[side]=target;if(current()?.type==='sftp')renderFiles();}}
function locateTransferJob(id){const j=jobs.find(j=>String(j.id)===String(id));if(!j)return;closeModal();hidePopover();let owner=sessions.find(s=>s.id===j.owner&&s.type==='sftp');if(!owner){owner={id:nextId++,type:'sftp',name:(j.ownerName||'任务文件')+' · 文件',state:'online',log:[],draft:''};sessions.push(owner);}directory.local=j.localDirectory;directory.remote=j.remoteDirectory;if(j.direction==='upload')directory.remote=j.path;else directory.local=j.path;seedFiles();active=owner.id;groupMode=false;render();toast('已定位任务目录',j.path);}
function queueJob(a){const source=files[a.direction==='upload'?'local':'remote'],entries=a.names.map((name,i)=>({...source.find(f=>f.name===name)||source.find(f=>f.name===a.sourceNames?.[i])||{type:'file',size:'大小待确认',mode:'-rw-r--r--'},name}));const job={entries,id:Date.now(),size:transferSize(a),owner:current()?.id,ownerName:current()?.name,ownerType:current()?.type,localDirectory:directory.local,remoteDirectory:directory.remote,name:a.names.join('、'),direction:a.direction,state:'queued',verify:a.verify||a.failChecksum,resume:a.resume!==false,failChecksum:a.failChecksum,progress:0,path:a.directory||directory[a.direction==='upload'?'remote':'local']};jobs.unshift(job);transferFeedback(job,'传输任务已加入队列');renderStatus();const refresh=()=>{renderStatus();refreshTransferView();};setTimeout(()=>{if(job.state==='queued'){job.state='running';job.progress=32;refresh();}},350);setTimeout(()=>{if(job.state==='running'){job.progress=67;refresh();}},1200);setTimeout(()=>{if(job.state==='running'){job.progress=100;job.state=job.verify?'verifying':'running';refresh();}},2200);setTimeout(()=>{if(['running','verifying'].includes(job.state)){job.state=job.failChecksum?'failed':'done';job.progress=100;job.error=job.failChecksum?'MD5 不一致 · 目标文件未标记完成':'';completeTransferFiles(job);transferFeedback(job,job.failChecksum?'文件校验失败':'文件传输已完成');refresh();}},3400);}

