function showWorkspaceTooltip(n){if(!n||!$('#popover').hidden||!$('#context-menu').hidden||!$('#modal-root').hidden)return;const t=$('#tooltip');if(n.dataset.tooltipKind==='host'){const h=hosts[+n.dataset.value],opened=sessions.filter(s=>s.address===h.address&&s.type===h.tag.toLowerCase()),online=opened.filter(s=>s.state==='online').length;t.innerHTML=`<strong>${hostOsIcon(h)}${esc(h.name)} <span class="host-protocol">${esc(h.tag.toUpperCase())}</span></strong><div class="hover-info"><span>${esc(h.tag)} · 已保存配置</span><span>${opened.length} 个独立会话</span></div><code>${esc(h.user)}@${esc(h.address)}:${h.port||22}</code><small>${esc(h.label)} · ${esc(h.os||'linux')}</small><small>${h.route?.length?'本机 → '+h.route.map(x=>esc(x.name||x.address)).join(' → ')+' → '+esc(h.name):'本机 → '+esc(h.name)+' · 直连'}</small>`;}else if(n.dataset.tooltipKind==='tab'){const id=n.dataset.value,g=String(id).startsWith('g')?groups.find(g=>g.id===+id.slice(1)):null,s=g?sessions.find(s=>s.id===g.members[0]):sessions.find(s=>s.id===+id);t.innerHTML=`<strong>${icon(g?'group':s?.type==='sftp'?'folder':'terminal')}${esc(g?'组 · '+g.name:s?.name)}</strong><div class="hover-info"><span>${g?g.members.length+' 个成员':s?.type==='local'?'Local Terminal':(s?.type||'').toUpperCase()}</span><span class="dot ${s?.state==='online'?'':'pending'}"></span><span>${s?.state==='online'?'在线':s?.state==='connecting'?'连接中':'已断开'}</span></div><code>${esc(s?.type==='local'?s.cwd:s?sessionEndpoint(s):'')}</code><small>${g?'终端组 · '+(g.direction==='column'?'上下分栏':'左右分栏'):s?.type==='local'?'/bin/zsh · 登录 Shell':'独立连接 · '+(s?.route?.length||0)+' 个跳板'}</small>`;}else if(n.dataset.act==='identity'){const s=current();t.innerHTML=`<strong>${esc(s?.name||'当前会话')}</strong><code>${esc(s?.type==='local'?s.cwd:sessionEndpoint(s))}</code><small>${s?.state==='online'?'已连接 · '+(s.type==='local'?'本地进程':'12 ms'):'未连接'} · 点击查看详情</small>`;}else if(n.dataset.act==='chain'){const s=current();t.innerHTML=`<strong>连接链路</strong><small>${s?.type==='local'?'本机 → ZSH':(s?.route?.length?s.route.map(h=>esc(h.name||h.address)).join(' → ')+' → ':'本机 → ')+esc(s?.name)}</small>`;}else if(n.dataset.act==='broadcast'){const a=approvals[currentGroup()?.id];t.innerHTML=`<strong>输入广播 · ${a?'已开启':'已关闭'}</strong><small>${a?a.members.map(id=>esc(sessions.find(s=>s.id===id)?.name)+' #'+id).join(' · '):'点击选择参与会话'}</small>`;}else t.textContent=n.dataset.tip;t.hidden=false;if(n.closest('#sidebar'))placeBeside(t,n);else placeOverlay(t,n.getBoundingClientRect(),!!n.closest('.statusbar')||!!n.closest('#assistant'));}
document.addEventListener('pointerover',e=>showWorkspaceTooltip(e.target.closest('[data-tip]')));
document.addEventListener('focusin',e=>showWorkspaceTooltip(e.target.closest('[data-tip]')));
document.addEventListener('pointerout',e=>{const n=e.target.closest('[data-tip]');if(n&&!n.contains(e.relatedTarget))$('#tooltip').hidden=true;});
document.addEventListener('focusout',()=>$('#tooltip').hidden=true);
document.addEventListener('input',e=>{if(e.target.id==='ai-input')aiData().draft=e.target.value;});
document.addEventListener('keydown',e=>{if(e.target.id!=='ai-input')return;if(e.key==='Enter'&&!e.shiftKey&&!e.metaKey&&!e.ctrlKey){e.preventDefault();$('#assistant [data-act="ai-send"]')?.click();}if(e.key==='/'&&!e.target.value) setTimeout(()=>$('#assistant [data-act="ai-attach"]').click(),0);});
let aiGesture=null;
document.addEventListener('pointerdown',e=>{const target=e.target.closest('[data-ai-drag],[data-ai-resize]');if(!target||e.target.closest('button'))return;const r=$('#assistant').getBoundingClientRect(),a=$('#app').getBoundingClientRect();aiMaximized=false;aiGesture={x:e.clientX,y:e.clientY,r:{x:r.left-a.left,y:r.top-a.top,w:r.width,h:r.height},resize:target.hasAttribute('data-ai-resize')?(target.dataset.aiResize||'se'):null};target.setPointerCapture(e.pointerId);e.preventDefault();});
document.addEventListener('pointermove',e=>{if(!aiGesture)return;const d=aiGesture,dx=e.clientX-d.x,dy=e.clientY-d.y;if(d.resize){let {x,y,w,h}=d.r;if(d.resize.includes('e'))w=Math.max(520,w+dx);if(d.resize.includes('s'))h=Math.max(354,h+dy);if(d.resize.includes('w')){w=Math.max(520,w-dx);x=d.r.x+d.r.w-w;}if(d.resize.includes('n')){h=Math.max(354,h-dy);y=d.r.y+d.r.h-h;}aiRect={x,y,w,h};}else aiRect={...d.r,x:d.r.x+dx,y:d.r.y+dy};positionAssistant();if(!$('#popover').hidden)positionPopover();});
document.addEventListener('pointerup',()=>aiGesture=null);

document.addEventListener('input',e=>{if(e.target.id==='replay-position'){replayPosition=+e.target.value;if(current()?.type==='history'){current().replayPosition=replayPosition;}const log=$('.terminal-scroll');if(log)log.innerHTML=current().log.slice(0,Math.max(1,Math.ceil(current().log.length*replayPosition/100))).map((l,i)=>logMarkup(l,current(),i)).join('');$('#replay-time').textContent=replayPosition+'%';}if(e.target.id==='terminal-search'){const q=e.target.value.toLowerCase(),rows=all('.terminal-line,.app-command');rows.forEach(n=>{n.classList.toggle('search-hit',!!q&&n.textContent.toLowerCase().includes(q));n.classList.remove('search-current');});searchCursor=0;const hits=all('.search-hit');if(hits[0])hits[0].classList.add('search-current');$('#search-count').textContent=q?(hits.length?'1 / '+hits.length:'无匹配'):'输入以查找';}});

function archivesDialog(){const states='<div class="forward-tabs">'+[['ready','归档'],['empty','空'],['error','读取失败']].map(([v,l])=>`<button data-act="archive-state" data-value="${v}">${l}</button>`).join('')+'</div>';modal('历史归档','按会话读取已保存记录；回放只读，实时会话继续运行。',states+(archiveState==='empty'?'<div class="forward-empty">'+icon('history')+'<strong>还没有历史归档</strong><p>启用会话日志后，记录将显示在这里。</p></div>':archiveState==='error'?'<div class="error-text">无法打开历史索引 · permission denied。<button class="text-button" data-act="archive-state" data-value="ready">重试</button></div>':`<button class="theme-option" data-act="archive-open" data-value="ready"><span>${icon('terminal')} ${esc(current()?.name||'会话')}<small>今天 10:18–10:24 · 6 分钟 · 完整</small></span>${icon('chevron')}</button><button class="theme-option" data-act="archive-open" data-value="gap"><span>${icon('alert')} prod-web-01<small>昨天 18:00–18:30 · 有记录缺口</small></span>${icon('chevron')}</button>`),'<button class="button secondary" data-act="close-modal">关闭</button>');}
document.addEventListener('change',e=>{if(!e.target.hasAttribute('data-broadcast-member'))return;const g=currentGroup(),id=+e.target.dataset.broadcastMember;if(!g||!broadcastDraft)return;const chosen=new Set(approvals[g.id]?.members||broadcastDraft.members);e.target.checked?chosen.add(id):chosen.delete(id);broadcastDraft={group:g.id,members:[...chosen]};if(approvals[g.id]){if(chosen.size>=2)approvals[g.id].members=[...chosen];else delete approvals[g.id];}renderStatus();broadcastPopover($('#broadcast'));});
document.addEventListener('paste',e=>{if(!e.target.classList.contains('command-input')||!e.clipboardData)return;const text=e.clipboardData.getData('text');if(!text.includes('\n')||!Object.values(approvals).some(a=>a.members?.includes(active)))return;e.preventDefault();const source=current();confirmDialog('向参与广播的会话粘贴多行输入？',text,'确认粘贴',()=>{source.draft+=text;renderContent();toast('多行内容已放入输入区','按 Enter 发送前可继续检查。');});});
setInterval(()=>{if(current()?.type==='history'&&replayPlaying){replayPosition=Math.min(100,replayPosition+replaySpeed*2);if(replayPosition===100)replayPlaying=false;renderHistoryPage(current());}},1000);

window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==$('#modal-root object')?.contentWindow||e.data?.type!=='zerowork-connection')return;const {action,connection:h}=e.data;if(action==='cancel'){connectionDraftHostIndex=-1;closeModal();return;}if(!h)return;rememberConnectionHost(h);closeModal();renderHosts();if(action==='saved'){toast('连接已保存',h.name);return;}const type=h.protocol.toLowerCase();if(!['ssh','sftp'].includes(type)){const url='../kvm/index.html?'+new URLSearchParams({protocol:type,theme,hostName:h.name,address:h.address,user:h.user||'',port:String(h.port||22),route:JSON.stringify(h.route||[])});if(new URLSearchParams(location.search).has('integrated'))parent.postMessage({type:'zw-app-child',action:'route',url:new URL(url,location.href).href},location.protocol==='file:'?'*':location.origin);else location.href=url;return;}const n={id:nextId++,type,name:h.name,user:h.user,address:h.address,port:h.port||22,route:structuredClone(h.route||[]),cwd:h.user==='root'?'/root':'/home/'+h.user,state:type==='ssh'?'connecting':'online',log:[],draft:''};sessions.push(n);active=n.id;groupMode=false;render();if(type==='ssh')authDialog(n.id);else toast('SFTP 连接已打开');});
if(params.get('noteCommand')){current().draft=params.get('noteCommand');renderContent();}
if(params.get('noteContext')){assistantOpen=true;putAiAttachment('笔记上下文',{type:'note',source:'笔记工作台',text:params.get('noteContext')});renderAssistant();}
if(params.get('ai')==='1'){assistantOpen=true;renderAssistant();}

function closeGroupDialog(g){closeGroupTarget=g;modal('关闭终端组？',`将关闭「${g.name}」中的 ${g.members.length} 个会话。`,g.members.map(id=>{const s=sessions.find(s=>s.id===id);return `<div class="member"><span class="dot"></span><strong>${esc(s?.name)} · #${id}</strong><span class="badge">${s?.state==='online'?'在线':'未连接'}</span></div>`;}).join('')+`<label class="field"><span>关闭结果演示</span><select id="group-close-outcome"><option value="success">全部关闭成功</option><option value="partial">部分失败</option><option value="unknown">结果未知</option></select></label><p class="info-note">关闭后，这些会话的连接及运行任务将受到影响。</p>`,`<button class="button secondary" data-act="close-modal">取消</button><button class="button danger-solid" data-act="group-close-run">断开并关闭全部</button>`);}
function finishGroupClose(){const g=closeGroupTarget;if(!g)return;groupCloseRun={g,ids:[...g.members],index:0,closed:[],outcome:$('#group-close-outcome').value,stopped:false};modal('正在关闭终端组','按成员逐个关闭；停止后续不会撤销已完成的关闭。','<div id="group-close-progress"></div>','<button class="button secondary" data-act="group-close-stop">停止后续关闭</button>');stepGroupClose();}
function stepGroupClose(){const run=groupCloseRun;if(!run)return;if(run.index>=run.ids.length||run.stopped){completeGroupClose();return;}const id=run.ids[run.index],last=run.index===run.ids.length-1;if(!(last&&run.outcome!=='success'))run.closed.push(id);run.index++;$('#group-close-progress').innerHTML=run.ids.map((id,i)=>`<div class="member"><strong>会话 #${id}</strong><span class="badge ${run.closed.includes(id)?'good':''}">${run.closed.includes(id)?'已关闭':i<run.index?run.outcome==='unknown'?'结果未知':'关闭失败':'等待关闭'}</span></div>`).join('');setTimeout(stepGroupClose,650);}
function completeGroupClose(){const run=groupCloseRun;if(!run)return;groupCloseRun=null;const g=run.g;forwards=forwards.filter(f=>!run.closed.includes(f.owner));sessions=sessions.filter(s=>!run.closed.includes(s.id));g.members=g.members.filter(id=>!run.closed.includes(id));groups=groups.filter(g=>g.members.length);delete approvals[g.id];active=g.members[0]||sessions[0]?.id;groupMode=!!g.members.length;closeModal();render();if(run.closed.length===run.ids.length){toast('终端组已关闭',run.closed.length+' 个会话已断开');return;}modal('终端组关闭结果',run.stopped?'已停止后续关闭。':run.outcome==='unknown'?'有成员结果未知，请确认连接状态后再处理。':'部分成员关闭失败，其他成员已关闭。',`<div class="card"><strong>${run.closed.length} 个已关闭</strong><p>${g.members.length} 个${run.stopped?'未执行关闭':run.outcome==='unknown'?'结果未知':'关闭失败'} · 会话仍保持可见，请检查连接状态。</p></div><p class="info-note">未知结果不自动重试，原组及剩余会话仍可检查。</p>`,'<button class="button primary" data-act="close-modal">保留并检查</button>');}

function openHistory(source,gap=false){if(!source)return;if(source.type==='history')return;const h={id:nextId++,type:'history',name:'回放 · '+source.name,sourceId:source.id,sourceName:source.name,sourcePrompt:prompt(source),sourceGroup:currentGroup()?.id,state:'archive',log:JSON.parse(JSON.stringify(source.log)),gap,draft:'',cwd:source.cwd,timestamp:true,replayPosition:gap?35:100};sessions.push(h);active=h.id;groupMode=false;historyOn=false;replayPosition=h.replayPosition;replayPlaying=false;assistantOpen=false;}
function renderHistoryPage(h){if(!h||h.type!=='history')return;$('#content').innerHTML=`<div class="terminal-toolbar">${icon('history')}<strong>独立历史回放</strong><span class="badge">只读</span><span>${esc(h.sourceName)}</span><span class="spacer"></span><button class="text-button" data-act="export-log">导出日志 / 快照</button><button class="text-button" data-act="history-live">返回实时</button></div>${h.gap?'<div class="stale-note">记录缺口：10:20:04–10:20:27 · 缺失内容不重建，实时会话不受影响。</div>':''}<div class="history-strip"><button class="text-button" data-act="replay-play">${replayPlaying?'暂停':'播放'}</button><button class="text-button" data-act="replay-speed">${replaySpeed}×</button><span>10:18:32</span><input id="replay-position" type="range" min="0" max="100" value="${replayPosition}" aria-label="历史时间位置"><span id="replay-time">${replayPosition}%</span><span>10:24:12</span></div><div class="terminal-scroll history-document">${h.log.slice(0,Math.max(1,Math.ceil(h.log.length*replayPosition/100))).map((l,i)=>logMarkup(l,h,i)).join('')}</div>`;}

$('#review-size').addEventListener('change',e=>{$('#app').dataset.size=e.target.value;sidebarCollapsed=e.target.value==='compact';render();positionPopover();});
if(params.get('size')==='compact'){$('#review-size').value='compact';$('#app').dataset.size='compact';sidebarCollapsed=true;if(params.get('sidebar')==='expanded')sidebarManual=false;render();}

function togglePin(s){const pinned=!s.pinned,g=groups.find(g=>g.members.includes(s.id));if(g)g.members.forEach(id=>{const m=sessions.find(s=>s.id===id);if(m)m.pinned=false;});s.pinned=pinned;}

document.addEventListener('dragstart',e=>{const tab=e.target.closest('.tab'),pane=e.target.closest('[data-pane]');if(tab){dragTab=tab.dataset.value;e.dataTransfer.setData('text/plain',dragTab);}else if(pane&&groupMode){dragPane=+pane.dataset.pane;e.dataTransfer.setData('text/plain',String(dragPane));}});
document.addEventListener('dragover',e=>{if((dragTab&&e.target.closest('.tab'))||(dragPane&&e.target.closest('[data-pane]')))e.preventDefault();});
document.addEventListener('drop',e=>{const tab=e.target.closest('.tab'),pane=e.target.closest('[data-pane]');if(dragTab&&tab){e.preventDefault();if(dragTab===tab.dataset.value){dragTab=null;return;}tabOrder=all('.tab').map(t=>t.dataset.value);tabOrder.splice(tabOrder.indexOf(dragTab),1);tabOrder.splice(tabOrder.indexOf(tab.dataset.value),0,dragTab);renderTabs();}else if(dragPane&&pane){e.preventDefault();if(dragPane===+pane.dataset.pane){dragPane=null;return;}const g=currentGroup(),target=+pane.dataset.pane;g.members=g.members.filter(id=>id!==dragPane);g.members.splice(g.members.indexOf(target),0,dragPane);renderContent();}dragTab=null;dragPane=null;});
document.addEventListener('dragend',()=>{dragTab=null;dragPane=null;});
document.addEventListener('keydown',e=>{if(!$('#modal-root').hidden)return;if((e.metaKey||e.ctrlKey)&&/^[1-9]$/.test(e.key)){const tab=all('.tab')[+e.key-1];if(tab){e.preventDefault();switchSession(tab.dataset.value);}}if(e.ctrlKey&&e.key==='Tab'){e.preventDefault();const target=recentTabs.find(id=>id!==String(groupMode?'g'+currentGroup()?.id:active));if(target)switchSession(target);}});

function renderOtherPalette(s,input,p){let list=[],label='历史命令';if(s.draft.startsWith('@theme ')){const q=s.draft.slice(7).toLowerCase();list=[...themeCatalog.filter(([id,name])=>(id+' '+name).toLowerCase().includes(q)).map(([id])=>'@theme '+id),...('default'.startsWith(q)?['@theme default']:[])];label='主题参数';}else if(s.draft.startsWith('@grp ')){const q=s.draft.slice(5).toLowerCase();list=groups.map(g=>'@grp '+g.name).filter(x=>x.toLowerCase().includes(q));label='终端组参数';}else if(/^(cd |ls |cat |@dl )/.test(s.draft)&&s.draft.includes('/')){const prefix=s.draft.split(' ')[0]+' ';list=['/var/www/app/','/var/log/','/home/deploy/'].map(x=>prefix+x).filter(x=>x.startsWith(s.draft));label='路径候选';}else if(s.draft&&!s.draft.startsWith('@')){list=[...new Set(s.log.filter(l=>l.command&&!l.command.startsWith('@')).map(l=>l.command))].filter(x=>x.startsWith(s.draft)&&x!==s.draft);}if(!list.length){p.hidden=true;return;}p.innerHTML=`<div class="palette-head">${icon('history')}<strong>${label}</strong><span class="badge">采纳后编辑</span></div><div class="palette-list">${list.map((x,i)=>`<button class="palette-row ${i===0?'active':''}" data-act="adopt" data-session="${s.id}" data-value="${esc(x)}">${icon(label.startsWith('显式')?'folder':'history')}<code>${esc(x)}</code></button>`).join('')}</div><div class="palette-foot">↑↓ 选择 · ↵ 采纳，不执行 · Esc 保留输入</div>`;p.hidden=false;positionPalette(p,input);}
document.addEventListener('keydown',e=>{if(!$('#modal-root').hidden)return;if((e.metaKey||e.ctrlKey)&&['[',']'].includes(e.key)){e.preventDefault();const tabs=all('.tab'),i=tabs.findIndex(t=>t.getAttribute('aria-selected')==='true'),n=(i+(e.key===']'?1:-1)+tabs.length)%tabs.length;if(tabs[n])switchSession(tabs[n].dataset.value);}});

function remotePicker(state='ready',path='/var/log/'){const source=current();if(!source||source.type==='local'||source.type==='history'){modal('选择远端连接','从在线会话选择文件来源',`<div class="source-list">${sessions.filter(s=>['ssh','sftp'].includes(s.type)).map(s=>`<button class="button secondary" data-act="ai-remote-source" data-value="${s.id}">${connectionGlyph(s.type)}${esc(s.name)} · #${s.id}</button>`).join('')||'<p>暂无在线远端会话</p>'}</div>`,'<button class="button secondary" data-act="close-modal">取消</button>');return;}remoteAttachmentSource=remoteAttachmentSource||source.id;const entries=[{name:'nginx',type:'folder',size:'—'},{name:'error.log',type:'file',size:'12 KB'},{name:'app.log',type:'file',size:'8 KB'},{name:'deploy.yaml',type:'code',size:'2.1 KB'}];modal('附加远端文件',`${esc(sessions.find(s=>s.id===remoteAttachmentSource)?.name||source.name)} · 只读文件选择`,`${groupMode&&currentGroup()?`<label class="remote-source-field"><span>来源</span><select id="ai-remote-source-select" aria-label="远端文件来源">${currentGroup().members.map(id=>sessions.find(s=>s.id===id)).filter(s=>s&&['ssh','sftp'].includes(s.type)).map(s=>`<option value="${s.id}" ${s.id===remoteAttachmentSource?'selected':''} ${s.state!=='online'?'disabled':''}>${esc(s.name)} · #${s.id}${s.state!=='online'?' · 已断开':''}</option>`).join('')}</select></label>`:''}<div class="remote-nav"><button class="icon-btn" data-act="ai-remote-up" aria-label="上级目录">${icon('up')}</button><span class="breadcrumb">${esc(path)}</span></div><label class="file-search remote-filter">${icon('search')}<input id="remote-filter" aria-label="筛选远端附件" placeholder="筛选文件名…"></label><div class="remote-file-list"><table class="file-table attachment-table"><thead><tr><th></th><th>名称</th><th>大小</th><th>修改时间</th></tr></thead><tbody>${entries.map(f=>`<tr data-remote-file="${f.name}" data-act="${f.type==='folder'?'ai-remote-enter':'ai-remote-select'}" data-value="${esc(path+f.name)}" class="${remoteAttachmentSelection.has(path+f.name)?'selected':''}" aria-selected="${remoteAttachmentSelection.has(path+f.name)}"><td>${f.type==='folder'?'':`<input type="checkbox" tabindex="-1" ${remoteAttachmentSelection.has(path+f.name)?'checked':''}>`}</td><td>${fileTypeGlyph(f)}${f.type==='folder'?esc(f.name):`<button class="remote-filename-preview" data-act="ai-remote-preview" data-value="${esc(path+f.name)}" title="读取预览 ${esc(f.name)}">${esc(f.name)}</button>`}</td><td>${f.size}</td><td>今天 10:21</td></tr>`).join('')}</tbody></table></div>`,`<button class="button secondary" data-act="close-modal">取消</button><button id="remote-add-selected" class="button primary" data-act="ai-remote-add-selected" ${remoteAttachmentSelection.size?'':'disabled'}>附加所选文件</button>`);}
