function fileSortValue(f,field){if(field==='size'){const m=String(f.size).match(/([0-9.]+)\s*(B|KB|MB|GB)/i);return m?+m[1]*({B:1,KB:1024,MB:1048576,GB:1073741824}[m[2].toUpperCase()]):0;}const now=new Date(),v=String(f.modified),time=v.match(/(\d{1,2}):(\d{2})/);if(v==='刚刚')return now.getTime();const d=new Date(now.getFullYear(),now.getMonth(),now.getDate(),+(time?.[1]||0),+(time?.[2]||0));if(v.startsWith('昨天'))d.setDate(d.getDate()-1);const date=v.match(/(\d+)月(\d+)日/);if(date){d.setMonth(+date[1]-1,+date[2]);}return d.getTime();}
