function transferSize(action){const source=files[action.direction==='upload'?'local':'remote'],chosen=action.names.map(name=>source.find(f=>f.name===name));if(chosen.some(f=>!f||f.type==='folder'))return '大小待确认';const bytes=chosen.reduce((n,f)=>n+fileSortValue(f,'size'),0);return bytes>=1048576?(bytes/1048576).toFixed(1)+' MB':bytes>=1024?(bytes/1024).toFixed(1)+' KB':bytes+' B';}

